const names=["tofacitinib","baricitinib","upadacitinib","ruxolitinib","fedratinib","pacritinib","abrocitinib","filgotinib","peficitinib","delgocitinib","momelotinib","ritlecitinib","deucravacitinib","oclacitinib","deuruxolitinib","ivarmacitinib","povorcitinib","brepocitinib"];
const rows=[];
for(const n of names){
 let d; try{d=await tools.chembl({action:"drug",query:n,limit:3});}catch(e){rows.push({n,err:e.message});continue;}
 const arr=d.drugs||d.results||d.molecules||(Array.isArray(d)?d:[]);
 const m=arr.find(x=>(x.preferredName||"").toLowerCase()==n)||arr[0];
 if(!m){rows.push({n,none:JSON.stringify(d).slice(0,150)});continue;}
 let mech; try{mech=await tools.chembl({action:"mechanism",chemblId:m.moleculeChemblId});}catch(e){mech={err:e.message}}
 rows.push({n,id:m.moleculeChemblId,phase:m.maxPhase,appr:m.firstApproval,mech:(mech.mechanisms||[]).map(x=>x.targetName+"|"+x.mechanismOfAction+"|"+x.actionType+"|"+x.targetChemblId)});
}
text(JSON.stringify(rows,null,1));

